$ErrorActionPreference = "Stop"

if (!(Test-Path ".\game")) {
    Write-Host "ERROR: Ejecuta este parche desde la carpeta raiz del proyecto (la que contiene game\)." -ForegroundColor Red
    exit 1
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = ".\_ui_backup_$stamp"
New-Item -ItemType Directory -Path $backup -Force | Out-Null

# Guardar parches anteriores que pueden redefinir las mismas pantallas.
foreach ($candidate in @(
    ".\game\hos_ui.rpy",
    ".\game\zz_hos_reference_ui.rpy",
    ".\game\zzzzz_hos_showcase_ui.rpy"
)) {
    if (Test-Path $candidate) {
        Copy-Item $candidate $backup -Force
        Move-Item -LiteralPath $candidate -Destination ($candidate + ".disabled.$stamp") -Force
    }
}

New-Item -ItemType Directory -Path ".\game\images\ui\icons" -Force | Out-Null


# Asset: game/images/ui/hos_menu_showcase.png
@'

'@ | ForEach-Object {
    [IO.File]::WriteAllBytes(".\game\images\ui\hos_menu_showcase.png", [Convert]::FromBase64String($_.Trim()))
}


