    [IO.File]::WriteAllBytes(".\game\zzzzz_hos_showcase_ui.rpy", [Convert]::FromBase64String($_.Trim()))
}

@'

'@ | ForEach-Object {
    [IO.File]::WriteAllBytes(".\HOS_DIRECT_SAMPLE.md", [Convert]::FromBase64String($_.Trim()))
}

# Borrar compilados viejos para que Ren'Py use el nuevo layout.
Get-ChildItem ".\game" -Filter "*.rpyc" -Recurse -ErrorAction SilentlyContinue |
    Remove-Item -Force -ErrorAction SilentlyContinue

if (Test-Path ".\game\cache") {
    Remove-Item ".\game\cache" -Recurse -Force
}

Write-Host ""
Write-Host "====================================================" -ForegroundColor Cyan
Write-Host " NIGHTFALL v0.5 - HoS DIRECT SAMPLE UI INSTALADA" -ForegroundColor Cyan
Write-Host "====================================================" -ForegroundColor Cyan
Write-Host ""
Write-Host "Incluido:"
Write-Host "  + Menu principal visual aprobado"
Write-Host "  + Logo Nightfall original"
Write-Host "  + Fondo nocturno original"
Write-Host "  + Iconos HUD"
Write-Host "  + HUD tipo sandbox VN"
Write-Host "  + Dialogo inferior"
Write-Host "  + Mapa / navegacion"
Write-Host "  + Personajes"
Write-Host "  + Inventario"
Write-Host "  + Misiones"
Write-Host "  + Galeria/Event Log"
Write-Host "  + Guardar/Cargar 3x2"
Write-Host "  + Preferencias"
Write-Host "  + Developer Tools conservado (F2)"
Write-Host ""
Write-Host "Backup de parches UI anteriores: $backup"
Write-Host ""
Write-Host "Abre Ren'Py Launcher -> Launch Project." -ForegroundColor Green


